package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
)

// ErrAttachmentNotFound reports that no attachment exists with the given id.
// The caller maps it to 404.
var ErrAttachmentNotFound = errors.New("attachment not found")

// ErrAttachmentForbidden reports that the device in the path is not the
// device that created the attachment. The caller maps it to 403.
var ErrAttachmentForbidden = errors.New("attachment belongs to another device")

// ErrAttachmentIncomplete reports that a finish was attempted before every
// chunk arrived, or the received bytes do not add up to the declared total.
// The upload stays resumable; the caller maps it to 409.
var ErrAttachmentIncomplete = errors.New("attachment chunks are missing or shorter than the declared total")

// ErrAttachmentDigestMismatch reports that the assembled content does not
// hash to the declared digest. The attachment stays incomplete; the caller
// maps it to 422.
var ErrAttachmentDigestMismatch = errors.New("assembled content does not match the declared sha256")

// ErrAttachmentDigestConflict reports that a different-size completed content
// already exists under the same digest, so this upload cannot be finished or
// reused. The upload stays resumable; the caller maps it to 409.
var ErrAttachmentDigestConflict = errors.New("a completed content with the same digest but a different size exists")

// ErrAttachmentConflict reports that an attachment id is already taken — by
// another device, or by this device with different metadata. The original
// record is unchanged; the caller maps it to 409.
type ErrAttachmentConflict struct {
	ID string
}

func (e *ErrAttachmentConflict) Error() string {
	return fmt.Sprintf("attachment %q already exists with different owner or metadata", e.ID)
}

// ErrAttachmentSealed reports a chunk write to an upload that was already
// finished. A sealed attachment is immutable: every further chunk write —
// even a byte-identical resubmission — is rejected and the recorded state and
// content are left unchanged. The caller maps it to 409.
var ErrAttachmentSealed = errors.New("attachment is complete and no longer accepts chunks")

// ErrChunkInvalid reports a chunk that violates the upload's declared shape:
// an out-of-range index, a non-final chunk shorter than the declared chunk
// size, or a final chunk beyond the declared total. The caller maps it to
// 400; nothing is written.
type ErrChunkInvalid struct {
	Reason string
}

func (e *ErrChunkInvalid) Error() string { return e.Reason }

// ErrChunkConflict reports that a chunk index already holds different bytes.
// The first content is kept; the caller maps it to 409.
type ErrChunkConflict struct {
	Index int64
}

func (e *ErrChunkConflict) Error() string {
	return fmt.Sprintf("chunk %d already exists with different content", e.Index)
}

// ErrChunkNotFound reports that no chunk exists at the given index. The
// caller maps it to 404.
var ErrChunkNotFound = errors.New("chunk not found")

// Attachment is the stored metadata of one resumable upload.
type Attachment struct {
	ID         string
	DeviceID   string
	TotalBytes int64
	ChunkSize  int64
	SHA256     string
	Complete   bool
	Reused     bool
}

// CompleteResult reports the outcome of a successful (or repeated) finish.
type CompleteResult struct {
	ID       string `json:"attachmentId"`
	Size     int64  `json:"size"`
	SHA256   string `json:"sha256"`
	Complete bool   `json:"complete"`
	Reused   bool   `json:"reused"`
}

// chunkCount returns how many chunks the declared shape implies.
func (a Attachment) chunkCount() int64 {
	return (a.TotalBytes + a.ChunkSize - 1) / a.ChunkSize
}

// checkChunkShape validates index and len(data) against the declared
// totalBytes/chunkSize, returning *ErrChunkInvalid on any violation.
func (a Attachment) checkChunkShape(index int64, length int64) error {
	count := a.chunkCount()
	if index < 0 || index >= count {
		return &ErrChunkInvalid{Reason: fmt.Sprintf("chunk index %d is out of range [0, %d)", index, count)}
	}
	if index < count-1 {
		if length != a.ChunkSize {
			return &ErrChunkInvalid{Reason: fmt.Sprintf("non-final chunk %d must be exactly %d bytes", index, a.ChunkSize)}
		}
		return nil
	}
	remaining := a.TotalBytes - a.ChunkSize*(count-1)
	if length < 1 || length > remaining {
		return &ErrChunkInvalid{Reason: fmt.Sprintf("final chunk must be between 1 and %d bytes", remaining)}
	}
	return nil
}

// loadAttachmentTx loads an attachment row inside tx without any ownership
// judgment; an unknown id yields ErrAttachmentNotFound.
func loadAttachmentTx(tx *sql.Tx, id string) (Attachment, error) {
	var a Attachment
	var complete, reused int
	err := tx.QueryRow(
		`SELECT id, device_id, total_bytes, chunk_size, sha256, complete, reused
		 FROM attachments WHERE id = ?`, id,
	).Scan(&a.ID, &a.DeviceID, &a.TotalBytes, &a.ChunkSize, &a.SHA256, &complete, &reused)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return Attachment{}, ErrAttachmentNotFound
	case err != nil:
		return Attachment{}, err
	}
	a.Complete = complete != 0
	a.Reused = reused != 0
	return a, nil
}

// getAttachmentTx loads an attachment row inside tx and enforces ownership:
// an unknown id yields ErrAttachmentNotFound and a device other than the
// creator yields ErrAttachmentForbidden.
func getAttachmentTx(tx *sql.Tx, id, deviceID string) (Attachment, error) {
	a, err := loadAttachmentTx(tx, id)
	if err != nil {
		return Attachment{}, err
	}
	if a.DeviceID != deviceID {
		return Attachment{}, ErrAttachmentForbidden
	}
	return a, nil
}

// getAttachmentReadTx loads an attachment row inside tx and enforces read
// access: the creator, or a device the creator has granted access through
// SetAttachmentAccess, may read; any other device yields
// ErrAttachmentForbidden. An unknown id yields ErrAttachmentNotFound.
func getAttachmentReadTx(tx *sql.Tx, id, deviceID string) (Attachment, error) {
	a, err := loadAttachmentTx(tx, id)
	if err != nil {
		return Attachment{}, err
	}
	if a.DeviceID == deviceID {
		return a, nil
	}
	granted, err := attachmentAccessGrantedTx(tx, id, deviceID)
	if err != nil {
		return Attachment{}, err
	}
	if !granted {
		return Attachment{}, ErrAttachmentForbidden
	}
	return a, nil
}

// attachmentAccessGrantedTx reports whether deviceID currently holds read
// access to the attachment. Every (attachment, device) pair starts
// unauthorized, so an absent row means not granted.
func attachmentAccessGrantedTx(tx *sql.Tx, attachmentID, deviceID string) (bool, error) {
	var stored int
	err := tx.QueryRow(
		`SELECT authorized FROM attachment_access WHERE attachment_id = ? AND device_id = ?`,
		attachmentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// CreateAttachment registers a new resumable upload owned by deviceID.
//
//   - An unregistered device yields ErrDeviceNotFound; nothing is written.
//   - Re-posting identical metadata under the same device is idempotent
//     (created=false).
//   - An id already taken — by another device (even with identical metadata)
//     or by this device with different metadata — yields
//     *ErrAttachmentConflict; the original record is unchanged.
//
// The check and the insert run in one serialized transaction and commit
// synchronously, so a retry after a crash reaches the same decision.
func (s *Store) CreateAttachment(deviceID string, a Attachment) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	var totalBytes, chunkSize int64
	var digest string
	err = tx.QueryRow(
		`SELECT device_id, total_bytes, chunk_size, sha256 FROM attachments WHERE id = ?`, a.ID,
	).Scan(&owner, &totalBytes, &chunkSize, &digest)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO attachments (id, device_id, total_bytes, chunk_size, sha256, complete, reused)
			 VALUES (?, ?, ?, ?, ?, 0, 0)`,
			a.ID, deviceID, a.TotalBytes, a.ChunkSize, a.SHA256,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID || totalBytes != a.TotalBytes || chunkSize != a.ChunkSize || digest != a.SHA256 {
		return false, &ErrAttachmentConflict{ID: a.ID}
	}
	return false, tx.Commit()
}

// PutChunk stores one chunk of an upload, durably, inside one transaction.
//
// Ownership and shape are enforced first: an unknown attachment yields
// ErrAttachmentNotFound, a non-creator device ErrAttachmentForbidden, and an
// out-of-range index or wrong length *ErrChunkInvalid — none of these write
// anything. A finished upload is sealed: any further chunk write, even a
// byte-identical resubmission, yields ErrAttachmentSealed and changes
// nothing. On an open upload, re-submitting identical bytes for an existing
// index is idempotent (created=false); different bytes for the same index
// yield *ErrChunkConflict and the first content is kept. Chunks may arrive in
// any order.
func (s *Store) PutChunk(deviceID, attachmentID string, index int64, data []byte) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentTx(tx, attachmentID, deviceID)
	if err != nil {
		return false, err
	}
	// A sealed upload is immutable: reject every further write before any
	// shape check or content comparison, so the recorded state and content
	// cannot change once the finish committed.
	if a.Complete {
		return false, ErrAttachmentSealed
	}
	if err := a.checkChunkShape(index, int64(len(data))); err != nil {
		return false, err
	}

	var existing []byte
	err = tx.QueryRow(
		`SELECT data FROM attachment_chunks WHERE attachment_id = ? AND idx = ?`,
		attachmentID, index,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO attachment_chunks (attachment_id, idx, data) VALUES (?, ?, ?)`,
			attachmentID, index, data,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if !bytesEqual(existing, data) {
		return false, &ErrChunkConflict{Index: index}
	}
	return false, tx.Commit()
}

// reuseContentTx resolves the digest-addressed content reuse decision inside
// tx: it returns reused=true when finished content with the same digest and
// size already exists (the bytes are not copied), reused=false when no such
// content exists yet (the caller inserts it), and ErrAttachmentDigestConflict
// when a finished content carries the same digest but a different size. That
// last state cannot arise from honest chunk assembly without a hash collision,
// but it must never silently reuse mismatched bytes.
func reuseContentTx(tx *sql.Tx, digest string, size int64) (bool, error) {
	var contentSize int64
	err := tx.QueryRow(
		`SELECT size FROM attachment_contents WHERE sha256 = ?`, digest,
	).Scan(&contentSize)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, err
	case contentSize != size:
		return false, ErrAttachmentDigestConflict
	default:
		return true, nil
	}
}

// CompleteAttachment seals an upload: every declared chunk must be present
// and their lengths must add up to the declared total, after which the
// concatenated content must hash to the declared digest.
//
//   - Unknown attachment: ErrAttachmentNotFound; non-creator device:
//     ErrAttachmentForbidden.
//   - Missing chunks or a total-length mismatch: ErrAttachmentIncomplete; the
//     upload stays resumable.
//   - Digest mismatch: ErrAttachmentDigestMismatch; the upload stays
//     incomplete.
//   - A completed content with the same digest but a different size:
//     ErrAttachmentDigestConflict; the upload stays resumable.
//   - A completed content with the same digest and size is reused: the bytes
//     are not copied and the result carries Reused=true.
//
// A successful finish is persisted with its result, so repeating the call
// returns the same result without recomputing anything.
func (s *Store) CompleteAttachment(deviceID, attachmentID string) (CompleteResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return CompleteResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentTx(tx, attachmentID, deviceID)
	if err != nil {
		return CompleteResult{}, err
	}
	if a.Complete {
		// A repeat finish returns the recorded result unchanged.
		return CompleteResult{
			ID:       a.ID,
			Size:     a.TotalBytes,
			SHA256:   a.SHA256,
			Complete: true,
			Reused:   a.Reused,
		}, tx.Commit()
	}

	rows, err := tx.Query(
		`SELECT idx, data FROM attachment_chunks WHERE attachment_id = ? ORDER BY idx ASC`,
		attachmentID,
	)
	if err != nil {
		return CompleteResult{}, err
	}
	var content []byte
	var received int64
	var total int64
	var prevIndex int64 = -1
	complete := true
	for rows.Next() {
		var idx int64
		var data []byte
		if err := rows.Scan(&idx, &data); err != nil {
			_ = rows.Close()
			return CompleteResult{}, err
		}
		if idx != prevIndex+1 {
			complete = false
		}
		prevIndex = idx
		received++
		total += int64(len(data))
		content = append(content, data...)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return CompleteResult{}, err
	}
	_ = rows.Close()

	if !complete || received != a.chunkCount() || total != a.TotalBytes {
		return CompleteResult{}, ErrAttachmentIncomplete
	}

	sum := sha256.Sum256(content)
	if hex.EncodeToString(sum[:]) != a.SHA256 {
		return CompleteResult{}, ErrAttachmentDigestMismatch
	}

	// Content is addressed by digest: an existing row means another finished
	// attachment already stored these bytes.
	reused, err := reuseContentTx(tx, a.SHA256, a.TotalBytes)
	if err != nil {
		return CompleteResult{}, err
	}
	if !reused {
		if _, err := tx.Exec(
			`INSERT INTO attachment_contents (sha256, size, data) VALUES (?, ?, ?)`,
			a.SHA256, a.TotalBytes, content,
		); err != nil {
			return CompleteResult{}, err
		}
	}

	if _, err := tx.Exec(
		`UPDATE attachments SET complete = 1, reused = ? WHERE id = ?`,
		boolToInt(reused), attachmentID,
	); err != nil {
		return CompleteResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return CompleteResult{}, err
	}
	return CompleteResult{
		ID:       a.ID,
		Size:     a.TotalBytes,
		SHA256:   a.SHA256,
		Complete: true,
		Reused:   reused,
	}, nil
}

// GetAttachment returns the stored metadata of an upload together with the
// sorted indices of the chunks received so far. An unknown id yields
// ErrAttachmentNotFound; a device that is neither the creator nor a granted
// reader yields ErrAttachmentForbidden.
func (s *Store) GetAttachment(deviceID, attachmentID string) (Attachment, []int64, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return Attachment{}, nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentReadTx(tx, attachmentID, deviceID)
	if err != nil {
		return Attachment{}, nil, err
	}

	rows, err := tx.Query(
		`SELECT idx FROM attachment_chunks WHERE attachment_id = ? ORDER BY idx ASC`,
		attachmentID,
	)
	if err != nil {
		return Attachment{}, nil, err
	}
	indices := make([]int64, 0)
	for rows.Next() {
		var idx int64
		if err := rows.Scan(&idx); err != nil {
			_ = rows.Close()
			return Attachment{}, nil, err
		}
		indices = append(indices, idx)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return Attachment{}, nil, err
	}
	_ = rows.Close()

	return a, indices, tx.Commit()
}

// GetAttachmentChunk returns the bytes stored at index. An unknown attachment
// yields ErrAttachmentNotFound and a device that is neither the creator nor a
// granted reader yields ErrAttachmentForbidden.
// For a known attachment, a negative index or one beyond the declared chunk
// range yields *ErrChunkInvalid (the caller maps it to 400); an in-range index
// with no stored chunk yields ErrChunkNotFound (404).
func (s *Store) GetAttachmentChunk(deviceID, attachmentID string, index int64) ([]byte, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := getAttachmentReadTx(tx, attachmentID, deviceID)
	if err != nil {
		return nil, err
	}
	// The path index is already a non-negative decimal; reject one outside the
	// shape the creator declared so out-of-range reads fail as a 400 rather than
	// masquerading as a missing chunk (404).
	if index < 0 || index >= a.chunkCount() {
		return nil, &ErrChunkInvalid{Reason: fmt.Sprintf("chunk index %d is out of range [0, %d)", index, a.chunkCount())}
	}

	var data []byte
	err = tx.QueryRow(
		`SELECT data FROM attachment_chunks WHERE attachment_id = ? AND idx = ?`,
		attachmentID, index,
	).Scan(&data)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrChunkNotFound
	case err != nil:
		return nil, err
	}
	return data, tx.Commit()
}

// SetAttachmentAccess grants or revokes targetDeviceID's read access to the
// attachment, on behalf of callerDeviceID. Every (attachment, device) pair
// starts unauthorized, so the first grant is the first write for the pair
// (changed=true); repeating the state that already holds writes nothing and
// reports changed=false. An unknown attachment yields ErrAttachmentNotFound,
// a caller other than the creator ErrAttachmentForbidden, and an unregistered
// target device ErrDeviceNotFound — none of these write anything. The lookup
// and the write run in one serialized transaction, so concurrent grant/revoke
// calls each commit completely and the final state matches the last committed
// action. Access only widens the read paths; chunk writes and the finish stay
// creator-only, and a revoke never deletes stored chunks or sealed content.
func (s *Store) SetAttachmentAccess(callerDeviceID, attachmentID, targetDeviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	a, err := loadAttachmentTx(tx, attachmentID)
	if err != nil {
		return false, err
	}
	if a.DeviceID != callerDeviceID {
		return false, ErrAttachmentForbidden
	}
	exists, err := DeviceExistsTx(tx, targetDeviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, ErrDeviceNotFound
	}

	current, err := attachmentAccessGrantedTx(tx, attachmentID, targetDeviceID)
	if err != nil {
		return false, err
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO attachment_access (attachment_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (attachment_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		attachmentID, targetDeviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}
	return true, nil
}

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

package server

import (
	"encoding/json"
	"errors"
	"io"
	"mime"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// maxChunkBytes caps a single inbound chunk body.
const maxChunkBytes = 64 << 20

type attachmentRequest struct {
	ID         string          `json:"attachmentId"`
	TotalBytes json.RawMessage `json:"totalBytes"`
	ChunkSize  json.RawMessage `json:"chunkSize"`
	SHA256     string          `json:"sha256"`
}

// handleCreateAttachment registers a resumable chunked upload for the device
// in the path. The body is strict JSON carrying the stable attachment id, the
// declared total size and chunk size (positive integers) and the lowercase
// hex SHA-256 of the final content. Any malformed input is a 400 JSON error
// and writes nothing; an unregistered device is a 404; an id already taken —
// by another device, or by this device with different metadata — is a 409
// that leaves the original record untouched.
func handleCreateAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty

	var req attachmentRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.ID == "" {
		writeError(w, http.StatusBadRequest, "attachmentId must be a non-empty string")
		return
	}
	totalBytes, ok := parsePositiveInt(req.TotalBytes)
	if !ok {
		writeError(w, http.StatusBadRequest, "totalBytes must be a positive integer")
		return
	}
	chunkSize, ok := parsePositiveInt(req.ChunkSize)
	if !ok {
		writeError(w, http.StatusBadRequest, "chunkSize must be a positive integer")
		return
	}
	if !isLowerHexSHA256(req.SHA256) {
		writeError(w, http.StatusBadRequest, "sha256 must be 64 lowercase hexadecimal characters")
		return
	}

	created, err := s.CreateAttachment(deviceID, store.Attachment{
		ID:         req.ID,
		TotalBytes: totalBytes,
		ChunkSize:  chunkSize,
		SHA256:     req.SHA256,
	})
	if err != nil {
		var conflict *store.ErrAttachmentConflict
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "attachmentId already exists with a different owner or metadata: "+conflict.ID)
		default:
			writeError(w, http.StatusInternalServerError, "failed to create attachment")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"attachmentId": req.ID, "created": created})
}

// handlePutChunk stores one binary chunk of an upload. The request must be
// application/octet-stream; the index is zero-based and chunks may arrive in
// any order. An unknown attachment is a 404 and a non-creator device a 403; a
// wrong content type, an out-of-range index, a short non-final chunk or a
// final chunk beyond the declared total is a 400 — none of these write
// anything. Re-submitting identical bytes is idempotent; different bytes for
// the same index are a 409 and the first content is kept. Once the upload is
// finished it is sealed: every further chunk write, even a byte-identical
// one, is a 409 and the stored content is unchanged.
func handlePutChunk(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/octet-stream" {
		writeError(w, http.StatusBadRequest, "Content-Type must be application/octet-stream")
		return
	}

	index, ok := parseCursorPath(r.PathValue("index"))
	if !ok {
		writeError(w, http.StatusBadRequest, "chunk index must be a non-negative integer")
		return
	}

	r.Body = http.MaxBytesReader(w, r.Body, maxChunkBytes+1)
	data, err := io.ReadAll(r.Body)
	if err != nil || int64(len(data)) > maxChunkBytes {
		writeError(w, http.StatusBadRequest, "chunk body is too large")
		return
	}

	created, err := s.PutChunk(deviceID, attachmentID, index, data)
	if err != nil {
		var invalid *store.ErrChunkInvalid
		var conflict *store.ErrChunkConflict
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.Is(err, store.ErrAttachmentSealed):
			writeError(w, http.StatusConflict, "attachment is complete and no longer accepts chunks")
		case errors.As(err, &invalid):
			writeError(w, http.StatusBadRequest, invalid.Reason)
		case errors.As(err, &conflict):
			writeError(w, http.StatusConflict, "chunk already exists with different content")
		default:
			writeError(w, http.StatusInternalServerError, "failed to store chunk")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{"index": index, "created": created})
}

// handleCompleteAttachment seals an upload. Only the creating device may
// finish it (others get a 403; an unknown attachment a 404). Missing chunks
// or a total-length mismatch are a 409 and leave the upload resumable; a
// digest mismatch is a 422 and leaves it incomplete. When another finished
// attachment already holds the same digest and size, the content is reused
// without copying bytes (reused=true); the same digest at a different size is
// a 409. A successful or repeated finish returns the same recorded result.
func handleCompleteAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	result, err := s.CompleteAttachment(deviceID, attachmentID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.Is(err, store.ErrAttachmentIncomplete):
			writeError(w, http.StatusConflict, "chunks are missing or do not add up to the declared total")
		case errors.Is(err, store.ErrAttachmentDigestMismatch):
			writeError(w, http.StatusUnprocessableEntity, "assembled content does not match the declared sha256")
		case errors.Is(err, store.ErrAttachmentDigestConflict):
			writeError(w, http.StatusConflict, "a completed content with the same digest but a different size exists")
		default:
			writeError(w, http.StatusInternalServerError, "failed to complete attachment")
		}
		return
	}

	writeJSON(w, http.StatusOK, result)
}

// handleGetAttachment returns the reader's view of an upload: the original
// metadata, the sorted indices received so far and the completion status. The
// creator and any device granted access through the access endpoint see the
// same body; any other device gets a 403, an unknown attachment a 404.
func handleGetAttachment(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	a, indices, err := s.GetAttachment(deviceID, attachmentID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		default:
			writeError(w, http.StatusInternalServerError, "failed to load attachment")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"attachmentId":   a.ID,
		"totalBytes":     a.TotalBytes,
		"chunkSize":      a.ChunkSize,
		"sha256":         a.SHA256,
		"complete":       a.Complete,
		"receivedChunks": indices,
	})
}

// handleGetChunk streams one stored chunk back to the creator or a granted
// reader. An empty identifier is rejected by the path guard; an illegal index
// is a 400; an unknown attachment or a chunk that never arrived is a 404; any
// other device is a 403.
func handleGetChunk(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	index, ok := parseCursorPath(r.PathValue("index"))
	if !ok {
		writeError(w, http.StatusBadRequest, "chunk index must be a non-negative integer")
		return
	}

	data, err := s.GetAttachmentChunk(deviceID, attachmentID, index)
	if err != nil {
		var invalid *store.ErrChunkInvalid
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrChunkNotFound):
			writeError(w, http.StatusNotFound, "chunk not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.As(err, &invalid):
			writeError(w, http.StatusBadRequest, invalid.Reason)
		default:
			writeError(w, http.StatusInternalServerError, "failed to load chunk")
		}
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(data)
}

// handleSetAttachmentAccess grants or revokes a registered device's read
// access to one attachment. Every (attachment, device) pair starts
// unauthorized, so the first grant is the first write; repeating the current
// state is idempotent (changed=false). Only the creator may change access: a
// non-creator caller gets a 403 and an unknown attachment a 404, neither
// touching any access state. A rejected request (bad content type, malformed
// JSON, trailing content, empty or mistyped fields, unknown action) is a 400
// JSON error and writes nothing; an unregistered target device is a 404 JSON
// error. A granted device reads the same metadata and chunk bytes as the
// creator; a revoke returns its reads to 403 at once and never deletes
// stored chunks or sealed content.
func handleSetAttachmentAccess(s *app.App, w http.ResponseWriter, r *http.Request) {
	deviceID := r.PathValue("deviceId")         // route pattern + guard guarantee non-empty
	attachmentID := r.PathValue("attachmentId") // route pattern + guard guarantee non-empty

	var req permissionRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	var authorized bool
	switch req.Action {
	case "grant":
		authorized = true
	case "revoke":
		authorized = false
	default:
		writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
		return
	}

	changed, err := s.SetAttachmentAccess(deviceID, attachmentID, req.DeviceID, authorized)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrAttachmentNotFound):
			writeError(w, http.StatusNotFound, "attachment not found")
		case errors.Is(err, store.ErrAttachmentForbidden):
			writeError(w, http.StatusForbidden, "attachment belongs to another device")
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		default:
			writeError(w, http.StatusInternalServerError, "failed to update attachment access")
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"deviceId":   req.DeviceID,
		"authorized": authorized,
		"changed":    changed,
	})
}

// isLowerHexSHA256 reports whether s is exactly 64 lowercase hex characters.
func isLowerHexSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// Package app is the composition root: it opens the one shared database and
// constructs the three independently reusable internal services — the change
// event service, the permission service and the CRDT state service — wiring
// them together only through their internal interfaces.
//
// The services share one SQLite connection (the kernel opens a single
// pooled connection with immediate transactions), so a change commit, a CRDT
// submission or compaction, and a permission change are serialized on the
// same connection and leave no half-written batch. The change event and CRDT
// services take their registration-and-authorization verdict from the
// permission service inside their own transactions (events.Gate / crdt.Gate),
// and the permission service fans a committed revoke out to their
// subscription registries through authz.RevokeSink. No service reaches into
// another service's tables or fields.
//
// App is the single object the entry and HTTP layers use. It promotes each
// service's input/output boundary as its methods while hiding the wiring; it
// adds no authentication and exposes no endpoint of its own.
package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/authz"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// App composes the durable kernel and the three internal services over one
// shared database connection.
type App struct {
	*store.Store

	events *events.Service
	crdt   *crdt.Service

	// Authz is the permission service. It is exposed so the HTTP layer can
	// grant/revoke and read authorization directly; the other services reach
	// it through their gates rather than this field.
	Authz *authz.Service
}

// Open opens (creating if needed) the SQLite database at path and constructs
// every internal service over it. The empty path opens a private in-memory
// database useful for tests. A construction failure closes the kernel and
// leaves nothing behind.
func Open(path string) (*App, error) {
	kernel, err := store.Open(path)
	if err != nil {
		return nil, err
	}

	// The permission service is built first: its gate is a constructor
	// dependency of the change event and CRDT services.
	permissions, err := authz.New(kernel)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	eventService, err := events.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	crdtService, err := crdt.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}

	// A committed revoke ends the affected live subscriptions in both
	// push channels. The dependency is an interface, registered once here, so
	// the permission service never names either subscriber concretely.
	permissions.AddRevokeSink(eventsRevokeSink{eventService})
	permissions.AddRevokeSink(crdtService)

	return &App{
		Store:  kernel,
		events: eventService,
		crdt:   crdtService,
		Authz:  permissions,
	}, nil
}

// eventsRevokeSink adapts the change event service's revoke hook to the
// permission service's RevokeSink interface.
type eventsRevokeSink struct{ e *events.Service }

func (s eventsRevokeSink) PermissionRevoked(documentID, deviceID string) {
	s.e.SignalRevoked(documentID, deviceID)
}

// Events returns the change event service.
func (a *App) Events() *events.Service { return a.events }

// CRDT returns the CRDT state service.
func (a *App) CRDT() *crdt.Service { return a.crdt }

// ---- Change event service boundary (promoted so the entry layer has one
// object; each method delegates verbatim to the events service). ----

// InterruptWaits wakes every parked long poll and every live change-log and
// CRDT subscription without closing the database, so an orderly shutdown
// drains waiting connections (long polls answer 503; subscriptions finish
// with the going-away close) instead of holding the drain hostage.
func (a *App) InterruptWaits() {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
}

// Closing reports whether shutdown has begun, covering both push channels.
func (a *App) Closing() bool {
	return a.events.Closing() || a.crdt.Closing()
}

// Close interrupts the in-memory observers, waits for every subscription
// handler to unregister and then releases the shared database handle.
func (a *App) Close() error {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
	a.events.WaitDrained()
	a.crdt.WaitDrained()
	return a.Store.Close()
}

